-- ============================================================
-- H2O SINGUR FITNESS GYM - MySQL DATABASE SCHEMA + SEED DATA
-- Generated for the PHP+MySQL version of the Gym System
--
-- HOW TO IMPORT (phpMyAdmin):
--   1. Create a database named  h2o_gym  (collation utf8mb4_unicode_ci)
--   2. Select it, open the Import tab, choose this file, press Go
--   3. Done. Default logins:  admin/admin123  owner/owner123
--                            staff/staff123  trainer/trainer123
--
-- If your host does not allow CREATE DATABASE, create the DB first
-- and simply skip/uncomment the two lines below.
-- ============================================================

-- CREATE DATABASE IF NOT EXISTS `h2o_gym` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- USE `h2o_gym`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------
-- USERS  (login accounts - passwords are bcrypt hashed)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(60) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `role` VARCHAR(20) NOT NULL DEFAULT 'staff',
  `name` VARCHAR(100) NOT NULL DEFAULT '',
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

