-- ------------------------------------------------------------
-- APP CONFIG  (key/value store; key 'app' holds the full settings JSON)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `app_config` (
  `k` VARCHAR(50) NOT NULL,
  `v` LONGTEXT,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

