-- ------------------------------------------------------------
-- CLIENTS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `clients` (
  `id` VARCHAR(24) NOT NULL,
  `firstName` VARCHAR(100) DEFAULT NULL,
  `lastName` VARCHAR(100) DEFAULT NULL,
  `dob` VARCHAR(10) DEFAULT NULL,
  `anniversary` VARCHAR(10) DEFAULT NULL,
  `gender` VARCHAR(20) DEFAULT NULL,
  `bloodGroup` VARCHAR(8) DEFAULT NULL,
  `aadhaar` VARCHAR(32) DEFAULT NULL,
  `occupation` VARCHAR(120) DEFAULT NULL,
  `mobile` VARCHAR(20) DEFAULT NULL,
  `whatsapp` VARCHAR(20) DEFAULT NULL,
  `email` VARCHAR(160) DEFAULT NULL,
  `address` VARCHAR(255) DEFAULT NULL,
  `city` VARCHAR(100) DEFAULT NULL,
  `state` VARCHAR(100) DEFAULT NULL,
  `pincode` VARCHAR(12) DEFAULT NULL,
  `emergencyName` VARCHAR(120) DEFAULT NULL,
  `emergencyPhone` VARCHAR(20) DEFAULT NULL,
  `goal` VARCHAR(120) DEFAULT NULL,
  `weight` VARCHAR(20) DEFAULT NULL,
  `height` VARCHAR(20) DEFAULT NULL,
  `disease` VARCHAR(255) DEFAULT NULL,
  `surgery` VARCHAR(255) DEFAULT NULL,
  `medications` VARCHAR(255) DEFAULT NULL,
  `plan` VARCHAR(50) DEFAULT NULL,
  `joinDate` VARCHAR(10) DEFAULT NULL,
  `renewalDate` VARCHAR(10) DEFAULT NULL,
  `fees` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `discount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `paymentMode` VARCHAR(30) DEFAULT NULL,
  `notes` TEXT,
  `status` VARCHAR(20) NOT NULL DEFAULT 'active',
  `photo` LONGTEXT,
  `createdAt` VARCHAR(35) DEFAULT NULL,
  `updatedAt` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_clients_status` (`status`),
  KEY `idx_clients_mobile` (`mobile`),
  KEY `idx_clients_renewal` (`renewalDate`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

