-- ------------------------------------------------------------
-- INVOICES  (client snapshot + line items stored as JSON)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `invoices` (
  `id` VARCHAR(24) NOT NULL,
  `number` VARCHAR(30) DEFAULT NULL,
  `date` VARCHAR(10) DEFAULT NULL,
  `color` VARCHAR(20) DEFAULT NULL,
  `gymName` VARCHAR(150) DEFAULT NULL,
  `gymPhone` VARCHAR(40) DEFAULT NULL,
  `gymAddress` VARCHAR(255) DEFAULT NULL,
  `gstNumber` VARCHAR(40) DEFAULT NULL,
  `clientJson` LONGTEXT,
  `itemsJson` LONGTEXT,
  `subtotal` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `discount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `taxRate` DECIMAL(6,2) NOT NULL DEFAULT 0,
  `taxAmount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(12,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_invoices_number` (`number`),
  KEY `idx_invoices_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

