-- ------------------------------------------------------------
-- MESSAGE TEMPLATES
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `templates` (
  `id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(150) DEFAULT NULL,
  `category` VARCHAR(50) DEFAULT NULL,
  `content` TEXT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_bday', 'Birthday Wish', 'birthday', 'Happy Birthday {name}! 🎂🎉 Wishing you a fantastic day filled with joy and health from all of us at {gym}! May this year bring you closer to your fitness goals!');
INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_anniv', 'Anniversary Wish', 'anniversary', 'Happy Anniversary {name}! 💐 Congratulations on another wonderful year! Enjoy your special day from the {gym} family!');
INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_renew', 'Renewal Reminder', 'renewal', 'Hi {name}, your {gym} membership is expiring on {date}. Renew now to keep crushing your fitness goals without interruption! 💪');
INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_welcome', 'Welcome Message', 'welcome', 'Welcome to {gym}, {name}! 🏋️‍♂️ We are thrilled to have you on board. Your fitness journey starts now. Let\'s make it happen!');
INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_absent', 'Absence Check-in', 'custom', 'Hi {name}, we noticed you haven\'t visited {gym} in a while. We miss you! Everything okay? Let us know if you need any help getting back on track. 💪');
INSERT INTO `templates` (`id`,`name`,`category`,`content`) VALUES ('tpl_1787748967100', 'Reminder for Class', 'custom', 'Hey {name}! Your next class is waiting for you! 💪\n\nGet ready to learn, train, and make progress at {gym}! 🔥\n\n📅 Class Date: {date}\n\nDon’t miss out on the opportunity to take another step toward your fitness goals. 🚀\n\n💪 Show up. Give your best. Get stronger.\n\nSee you at {gym}, {name}! 🙌');

-- ------------------------------------------------------------
-- TRAINERS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `trainers` (
  `id` VARCHAR(24) NOT NULL,
  `firstName` VARCHAR(100) DEFAULT NULL,
  `lastName` VARCHAR(100) DEFAULT NULL,
  `mobile` VARCHAR(20) DEFAULT NULL,
  `email` VARCHAR(160) DEFAULT NULL,
  `dob` VARCHAR(10) DEFAULT NULL,
  `specialization` VARCHAR(150) DEFAULT NULL,
  `certifications` VARCHAR(255) DEFAULT NULL,
  `shiftStart` VARCHAR(10) DEFAULT NULL,
  `shiftEnd` VARCHAR(10) DEFAULT NULL,
  `photo` LONGTEXT,
  `assignedClientsJson` LONGTEXT,
  `experience` INT NOT NULL DEFAULT 0,
  `salary` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `rating` DECIMAL(4,2) NOT NULL DEFAULT 0,
  `createdAt` VARCHAR(35) DEFAULT NULL,
  `updatedAt` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

