-- ------------------------------------------------------------
-- DIET PLANS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `diet_plans` (
  `id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(150) DEFAULT NULL,
  `goal` VARCHAR(100) DEFAULT NULL,
  `calories` INT DEFAULT NULL,
  `description` TEXT,
  `meals` MEDIUMTEXT,
  `assignedTo` VARCHAR(24) DEFAULT NULL,
  `createdAt` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `diet_plans` (`id`,`name`,`goal`,`calories`,`description`,`meals`,`assignedTo`,`createdAt`) VALUES ('Diet_Weight_Loss', '30-Day Weight Loss Plan', 'Weight Loss', 1800, 'High protein, low carb plan for steady weight loss', 'Breakfast | Oats + Banana + Almonds | 350\nLunch | Brown rice + Grilled chicken + Salad | 500\nSnack | Greek yogurt + Berries | 200\nDinner | Paneer + Veggies + Quinoa | 450', 'CLT1002', '2026-04-10T10:00:00.000Z');
INSERT INTO `diet_plans` (`id`,`name`,`goal`,`calories`,`description`,`meals`,`assignedTo`,`createdAt`) VALUES ('Diet_Muscle_Gain', 'Muscle Builder Plan', 'Muscle Gain', 2800, 'High calorie, high protein plan for muscle gain', 'Breakfast | 6 eggs + Toast + Peanut Butter | 600\nLunch | Brown rice + Chicken + Dal | 700\nSnack | Whey protein + Banana | 300\nDinner | Roti + Fish + Veggies | 600\nPre-bed | Cottage cheese + Almonds | 400', 'CLT1001', '2026-07-15T10:00:00.000Z');

-- ------------------------------------------------------------
-- EXERCISE PLANS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `exercise_plans` (
  `id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(150) DEFAULT NULL,
  `goal` VARCHAR(100) DEFAULT NULL,
  `duration` INT DEFAULT NULL,
  `description` TEXT,
  `workouts` MEDIUMTEXT,
  `assignedTrainer` VARCHAR(24) DEFAULT NULL,
  `assignedTo` VARCHAR(24) DEFAULT NULL,
  `createdAt` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `exercise_plans` (`id`,`name`,`goal`,`duration`,`description`,`workouts`,`assignedTrainer`,`assignedTo`,`createdAt`) VALUES ('Ex_Push_Pull_Legs', 'Push Pull Legs Split', 'Muscle Gain', 8, '6-day PPL split for hypertrophy', 'Monday | Bench Press | 4x8\nMonday | Incline DB Press | 3x10\nMonday | Triceps Pushdown | 3x12\nTuesday | Pull-ups | 4xAMRAP\nTuesday | Barbell Row | 4x8\nWednesday | Squats | 4x6\nWednesday | Leg Press | 3x10', 'TRN1001', 'CLT1001', '2026-07-15T10:00:00.000Z');
INSERT INTO `exercise_plans` (`id`,`name`,`goal`,`duration`,`description`,`workouts`,`assignedTrainer`,`assignedTo`,`createdAt`) VALUES ('Ex_Yoga_Flex', 'Flexibility & Mobility Flow', 'Flexibility', 4, 'Yoga-based mobility routine', 'Monday | Sun Salutation | 5 rounds\nWednesday | Hip Opening | 10 min\nFriday | Spinal Twist | 10 min', 'TRN1002', 'CLT1004', '2026-06-20T10:00:00.000Z');

-- ------------------------------------------------------------
-- GROUP CLASSES
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `classes` (
  `id` VARCHAR(24) NOT NULL,
  `name` VARCHAR(150) DEFAULT NULL,
  `type` VARCHAR(50) DEFAULT NULL,
  `trainerId` VARCHAR(24) DEFAULT NULL,
  `date` VARCHAR(10) DEFAULT NULL,
  `time` VARCHAR(10) DEFAULT NULL,
  `capacity` INT NOT NULL DEFAULT 0,
  `duration` INT NOT NULL DEFAULT 0,
  `fee` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `enrolledJson` LONGTEXT,
  `createdAt` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

