-- ------------------------------------------------------------
-- BODY MEASUREMENTS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `body_measurements` (
  `id` VARCHAR(30) NOT NULL,
  `clientId` VARCHAR(24) DEFAULT NULL,
  `date` VARCHAR(10) DEFAULT NULL,
  `weight` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `bodyFat` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `muscle` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `chest` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `waist` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `hips` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `arms` DECIMAL(8,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_bm_client` (`clientId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- FEEDBACK / REFERRALS / LOYALTY / SELF-REGISTRATIONS / FREEZES / CAMPAIGNS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `feedback` (
  `id` VARCHAR(30) NOT NULL,
  `clientId` VARCHAR(24) DEFAULT NULL,
  `rating` INT NOT NULL DEFAULT 0,
  `category` VARCHAR(50) DEFAULT NULL,
  `comments` TEXT,
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_feedback_client` (`clientId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `referrals` (
  `id` VARCHAR(30) NOT NULL,
  `referrerId` VARCHAR(24) DEFAULT NULL,
  `referredId` VARCHAR(24) DEFAULT NULL,
  `pointsAwarded` INT NOT NULL DEFAULT 0,
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `loyalty_points` (
  `id` VARCHAR(40) NOT NULL,
  `clientId` VARCHAR(24) DEFAULT NULL,
  `points` INT NOT NULL DEFAULT 0,
  `type` VARCHAR(30) DEFAULT NULL,
  `reason` VARCHAR(255) DEFAULT NULL,
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_loyalty_client` (`clientId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `self_registrations` (
  `id` VARCHAR(30) NOT NULL,
  `firstName` VARCHAR(100) DEFAULT NULL,
  `lastName` VARCHAR(100) DEFAULT NULL,
  `mobile` VARCHAR(20) DEFAULT NULL,
  `email` VARCHAR(160) DEFAULT NULL,
  `goal` VARCHAR(120) DEFAULT NULL,
  `plan` VARCHAR(50) DEFAULT NULL,
  `status` VARCHAR(20) DEFAULT 'pending',
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `freezes` (
  `id` VARCHAR(30) NOT NULL,
  `clientId` VARCHAR(24) DEFAULT NULL,
  `fromDate` VARCHAR(10) DEFAULT NULL,
  `toDate` VARCHAR(10) DEFAULT NULL,
  `reason` VARCHAR(255) DEFAULT NULL,
  `days` INT NOT NULL DEFAULT 0,
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `campaigns` (
  `id` VARCHAR(30) NOT NULL,
  `name` VARCHAR(150) DEFAULT NULL,
  `discount` VARCHAR(20) DEFAULT NULL,
  `valid` VARCHAR(10) DEFAULT NULL,
  `message` TEXT,
  `sentTo` INT NOT NULL DEFAULT 0,
  `date` VARCHAR(35) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- SERVER-SIDE BACKUPS  (auto/manual backup snapshots)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `backups` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `jsId` VARCHAR(40) DEFAULT NULL,
  `name` VARCHAR(190) DEFAULT NULL,
  `type` VARCHAR(20) DEFAULT 'manual',
  `size` VARCHAR(30) DEFAULT NULL,
  `date` VARCHAR(35) DEFAULT NULL,
  `dataJson` LONGTEXT,
  PRIMARY KEY (`id`),
  KEY `idx_backups_jsid` (`jsId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;

